package com.xenris.liquidwarsos;
import static com.xenris.liquidwarsos.World170ProbeTest.*;
import android.content.Intent;import android.graphics.Rect;import android.os.*;import android.view.*;import androidx.lifecycle.Lifecycle;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import com.xenris.liquidwarsos.activities.*;
@RunWith(AndroidJUnit4.class) public class Operations180ProbeTest {
 static OperationsSnapshot ops(){return new OperationsSnapshot(NativeInterface.operationsSnapshot(StaticBits.team,false));}
 static void apply(ActivityScenario<GameActivity> s){s.onActivity(a->{try{invoke(a,"setPlayerPositions");}catch(Exception e){throw new AssertionError(e);}});}
 static void advance(ActivityScenario<GameActivity> s,int steps){for(int n=0;n<steps;n++){if(n%10==0)apply(s);NativeInterface.stepDots();}}
 static void ready(ActivityScenario<GameActivity> s,Rect gl,Rect hud){s.onActivity(a->{a.findViewById(R.id.mySurfaceView).getGlobalVisibleRect(gl);a.findViewById(R.id.tactical_overlay).getGlobalVisibleRect(hud);});SystemClock.sleep(250);}
 static void button(ActivityScenario<GameActivity> s,Rect b,int index){final float[] xy=new float[2];s.onActivity(a->{try{TacticalOverlay v=a.findViewById(R.id.tactical_overlay);java.lang.reflect.Method m=TacticalOverlay.class.getDeclaredMethod("baseline"),w=TacticalOverlay.class.getDeclaredMethod("buttonWidth");m.setAccessible(true);w.setAccessible(true);float dp=context().getResources().getDisplayMetrics().density;xy[0]=b.left+10*dp+(index+.5f)*(Float)w.invoke(v);xy[1]=b.top+(Float)m.invoke(v)+24*dp;}catch(Exception e){throw new AssertionError(e);}});tap(xy[0],xy[1]);SystemClock.sleep(100);}
 static float[] screen(ActivityScenario<GameActivity> s,Rect b,int x,int y){float[] out=new float[2];s.onActivity(a->{MyGLSurfaceView v=a.findViewById(R.id.mySurfaceView);out[0]=b.left+v.camera.screenX(x,b.width());out[1]=b.top+v.camera.screenY(y,b.height());});return out;}
 @Test public void commandsAndCapture()throws Exception {
  Intent intent=prepare(1,18001,400,true,false);StaticBits.operationsMode=1;
  try(ActivityScenario<GameActivity> s=ActivityScenario.launch(intent)){
   frozen(s);Rect gl=new Rect(),hud=new Rect();ready(s,gl,hud);OperationsSnapshot start=ops();Assert.assertEquals(3,start.sites());int t=StaticBits.team,a=start.group(t,0),site=-1;long best=Long.MAX_VALUE;for(int k=0;k<start.sites();k++){int at=start.site(k);long d=(long)(start.raw[at]-start.raw[a+1])*(start.raw[at]-start.raw[a+1])+(long)(start.raw[at+1]-start.raw[a+2])*(start.raw[at+1]-start.raw[a+2]);if(d<best){best=d;site=k;}}
   int at=start.site(site),tx=start.raw[at],ty=start.raw[at+1];float[] xy=screen(s,gl,tx,ty);tap(xy[0],xy[1]);advance(s,30);OperationsSnapshot after=ops();int g=after.group(t,0);Assert.assertEquals("actual tap submits persistent native order",1,after.raw[g+3]);Assert.assertEquals(1,after.raw[g+7]);
   picture("ops180-01-order.jpg");long began=SystemClock.elapsedRealtime();int loops=0;while(ops().raw[ops().site(site)+2]!=t&&loops++<100){advance(s,100);SystemClock.sleep(15);}after=ops();Assert.assertEquals("actual troops capture site",t,after.raw[after.site(site)+2]);int count=NativeInterface.teamScore(t);advance(s,500);Assert.assertTrue("actual particles produced",NativeInterface.teamScore(t)>count);SystemClock.sleep(150);picture("ops180-02-captured.jpg");
   button(s,hud,5);advance(s,20);after=ops();Assert.assertTrue(after.split(t));Assert.assertTrue(after.raw[after.group(t,1)]>0);button(s,hud,3); // choose B
   button(s,hud,0); // draw
   byte[] walls=NativeInterface.modelTerrain();int x2=tx,y2=ty;for(int r=20;r<80;r+=5){int x=tx+r;if(x<780&&walls[ty*800+x]==0){x2=x;break;}}
   float[] end=screen(s,gl,x2,y2);long down=SystemClock.uptimeMillis();touch(down,0,xy[0],xy[1]);for(int n=1;n<=12;n++)touch(down,2,xy[0]+(end[0]-xy[0])*n/12,xy[1]+(end[1]-xy[1])*n/12);touch(down,1,end[0],end[1]);advance(s,100);after=ops();int b=after.group(t,1);Assert.assertEquals("draw commits B route",1,after.raw[b+3]);picture("ops180-draw-diagnostic.jpg");write("ops180-draw-diagnostic.json",new JSONObject().put("snapshot",new JSONArray(after.raw)).put("start_x",tx).put("end_x",x2).put("y",ty));Assert.assertTrue("draw has multiple waypoints, status="+after.feedback(t)+" n="+after.raw[b+7],after.raw[b+7]>1);Assert.assertEquals("A remains stopped after split",1,after.raw[after.group(t,0)+4]);SystemClock.sleep(150);picture("ops180-03-squads-route.jpg");
   button(s,hud,7);advance(s,20);Assert.assertEquals("stop selected B",1,ops().raw[ops().group(t,1)+4]);long hash=NativeInterface.stateHash();SystemClock.sleep(250);Assert.assertEquals("paused UI consumes no rule time",hash,NativeInterface.stateHash());
   s.moveToState(Lifecycle.State.CREATED);s.moveToState(Lifecycle.State.RESUMED);frozen(s);Assert.assertEquals("EGL resume preserves native squad orders",1,ops().raw[ops().group(t,1)+4]);picture("ops180-04-resume.jpg");
   write("ops180-commands.json",new JSONObject().put("status","PASS").put("tap_and_draw_real_touch",true).put("persistent_squads",true).put("site",site).put("capture_sim_ms",after.raw[2]).put("wall_ms",SystemClock.elapsedRealtime()-began).put("production",true).put("pause_resume",true).put("controlled_core_steps",true).put("normal_worker",false).put("models",0));
  }finally{StaticBits.operationsMode=0;}
 }
 @Test public void normalWorkerAndMap()throws Exception {
  Intent intent=prepare(54,18054,1000,false,false);StaticBits.operationsMode=1;
  try(ActivityScenario<GameActivity> s=ActivityScenario.launch(intent)){
   Rect gl=new Rect(),hud=new Rect();ready(s,gl,hud);long deadline=SystemClock.uptimeMillis()+15000;while(NativeInterface.playTimeMillis()==0&&SystemClock.uptimeMillis()<deadline)SystemClock.sleep(50);Assert.assertTrue(NativeInterface.playTimeMillis()>0);Assert.assertEquals(5,ops().sites());
   s.onActivity(a->{MyGLSurfaceView v=a.findViewById(R.id.mySurfaceView);v.camera.overview=true;v.camera.focus(800,480);});SystemClock.sleep(200);OperationsSnapshot before=ops();int t=StaticBits.team,g=before.group(t,0);int site=0;long dist=Long.MAX_VALUE;for(int k=0;k<before.sites();k++){int at=before.site(k);long d=(long)(before.raw[at]-before.raw[g+1])*(before.raw[at]-before.raw[g+1])+(long)(before.raw[at+1]-before.raw[g+2])*(before.raw[at+1]-before.raw[g+2]);if(d<dist){dist=d;site=k;}}int at=before.site(site);float[] p=screen(s,gl,before.raw[at],before.raw[at+1]);tap(p[0],p[1]);int start=NativeInterface.playTimeMillis();SystemClock.sleep(6500);OperationsSnapshot after=ops();Assert.assertTrue("normal worker runs",NativeInterface.playTimeMillis()-start>1500);Assert.assertTrue("command survives released finger",after.raw[after.group(t,0)+3]!=0);picture("ops180-05-normal-large.jpg");Debug.MemoryInfo memory=new Debug.MemoryInfo();Debug.getMemoryInfo(memory);write("ops180-normal.json",new JSONObject().put("status","PASS").put("normal_worker",true).put("map",54).put("units_per_team",1000).put("sim_advanced_ms",NativeInterface.playTimeMillis()-start).put("pss_kib",memory.getTotalPss()).put("screenshot","ops180-05-normal-large.jpg").put("human_play",false));
  }finally{StaticBits.operationsMode=0;}
 }
 @Test public void setupModeVisible()throws Exception {
  StaticBits.operationsMode=0;try(ActivityScenario<SinglePlayerGameSetupActivity> s=ActivityScenario.launch(new Intent(context(),SinglePlayerGameSetupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))){SystemClock.sleep(500);s.onActivity(a->{Assert.assertNotNull(a.findViewById(R.id.teamsize_spinner));});picture("ops180-00-setup.jpg");}
 }
}
